1	//! `paigasus-helikon-runtime-tokio` — the default ephemeral Tokio runner.
2	//!
3	//! [`TokioRunner`] implements [`paigasus_helikon_core::Runner`] by consuming
4	//! the agent's [`paigasus_helikon_core::AgentEvent`] stream and adding
5	//! run-level control (cancellation, timeout, aggregation) at the boundary. It
6	//! does not own the loop driver — the agent does (see ADR-13).
7	
8	use std::sync::{Arc, Mutex};
9	use std::time::Duration;
10	
11	use async_trait::async_trait;
12	use futures_core::stream::BoxStream;
13	use futures_util::stream::StreamExt as _;
14	use paigasus_helikon_core::{
15	    Agent, AgentEvent, AgentInput, CancellationToken, RunConfig, RunContext, RunError, RunResult,
16	    RunResultStreaming, Runner, Session, SessionRecorder,
17	};
18	
19	pub mod retry;
20	pub use retry::{RetryPolicy, RetryingModel};
21	
22	/// How a controlled run ended.
23	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
24	enum Outcome {
25	    Completed,
26	    Cancelled,
27	    TimedOut,
28	}
29	
30	/// Read handle for the outcome committed by [`controlled`].
31	struct OutcomeHandle(Arc<Mutex<Outcome>>);
32	
33	impl OutcomeHandle {
34	    fn get(&self) -> Outcome {
35	        *self.0.lock().unwrap()
36	    }
37	}
38	
39	/// Did the run reach a terminal event? Used to decide whether a late
40	/// cancel/timeout may override the collected outcome (SMA-421).
41	fn is_terminal(ev: &AgentEvent) -> bool {
42	    matches!(
43	        ev,
44	        AgentEvent::RunCompleted { .. } | AgentEvent::RunFailed { .. }
45	    )
46	}
47	
48	/// Wrap an agent event stream with cancel/deadline control.
49	///
50	/// Passes agent events through. On cancellation or deadline it commits the
51	/// reason into the returned handle and ends the stream (dropping the inner
52	/// stream cancels nested in-flight awaits within one poll). The outcome is
53	/// committed *before* the terminating `None`, so a caller reading the handle
54	/// after draining never sees a stale value.
55	fn controlled(
56	    mut stream: BoxStream<'static, AgentEvent>,
57	    cancel: CancellationToken,
58	    timeout: Option<Duration>,
59	) -> (BoxStream<'static, AgentEvent>, OutcomeHandle) {
60	    let cell = Arc::new(Mutex::new(Outcome::Completed));
61	    let handle = OutcomeHandle(Arc::clone(&cell));
62	    let out = async_stream::stream! {
63	        let sleep = async move {
64	            match timeout {
65	                Some(d) => tokio::time::sleep(d).await,
66	                None => std::future::pending::<()>().await,
67	            }
68	        };
69	        tokio::pin!(sleep);
70	        loop {
71	            tokio::select! {
72	                biased;
73	                maybe_ev = stream.next() => {
74	                    match maybe_ev {
75	                        Some(ev) => yield ev,
76	                        None => break, // inner stream done => Completed (default)
77	                    }
78	                }
79	                () = cancel.cancelled() => {
80	                    *cell.lock().unwrap() = Outcome::Cancelled;
81	                    break;
82	                }
83	                () = &mut sleep => {
84	                    *cell.lock().unwrap() = Outcome::TimedOut;
85	                    break;
86	                }
87	            }
88	        }
89	    };
90	    (Box::pin(out), handle)
91	}
92	
93	/// Snapshot the session into the merged input and seed a recorder with the
94	/// run's new-turn messages. A read failure is a hard error: the run cannot
95	/// faithfully resume from an unreadable session, so it fails before the agent
96	/// starts. (The write side, by contrast, is best-effort — see `finalize`.)
97	async fn load_and_record(
98	    session: &Arc<dyn Session>,
99	    agent_name: &str,
100	    input: AgentInput,
101	) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
102	    let snapshot = session
103	        .snapshot()
104	        .await
105	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
106	    let mut recorder = SessionRecorder::new(agent_name);
107	    recorder.record_input(&input.messages);
108	
109	    let mut merged = AgentInput::new();
110	    merged.messages = snapshot.messages;
111	    merged.messages.extend(input.messages);
112	    Ok((merged, Arc::new(Mutex::new(recorder))))
113	}
114	
115	/// Post-run finalization: drain the recorder and append the run's events.
116	/// Persistence is best-effort — an append error is logged, never propagated, so
117	/// the run's outcome (Ok / Cancelled / Timeout / Agent error) is unchanged.
118	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
119	    let events = recorder
120	        .lock()
121	        .expect("session recorder mutex poisoned")
122	        .drain();
123	    if let Err(e) = session.append(&events).await {
124	        tracing::warn!(
125	            error = %e,
126	            "session persistence failed during finalize; run outcome unaffected"
127	        );
128	    }
129	}
130	
131	/// The default ephemeral execution backend. Stateless.
132	#[derive(Debug, Clone, Copy, Default)]
133	pub struct TokioRunner;
134	
135	#[async_trait]
136	impl<Ctx> Runner<Ctx> for TokioRunner
137	where
138	    Ctx: Send + Sync + 'static,
139	{
140	    async fn run(
141	        &self,
142	        agent: &(dyn Agent<Ctx> + '_),
143	        ctx: RunContext<Ctx>,
144	        input: AgentInput,
145	        config: RunConfig,
146	    ) -> Result<RunResult, RunError> {
147	        let timeout = config.timeout;
148	        let ctx = ctx.with_run_config(config);
149	        let cancel = ctx.cancel().clone();
150	        let session = ctx.session().clone();
151	        let failure = ctx.failure_handle();
152	
153	        // Load persisted history and seed the recorder with the new turn.
154	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
155	
156	        let stream = agent.run(ctx, merged).await?;
157	        let (controlled_stream, outcome) = controlled(stream, cancel, timeout);
158	        let rec_inspect = Arc::clone(&recorder);
159	        let recorded = controlled_stream
160	            .inspect(move |ev| {
161	                rec_inspect
162	                    .lock()
163	                    .expect("session recorder mutex poisoned")
164	                    .observe(ev)
165	            })
166	            .boxed();
167	        // Do NOT `?`-short-circuit before finalize: agent failures surface as
168	        // collect()=Err, and finalize must still run.
169	        let collected = RunResultStreaming::with_failure(recorded, failure)
170	            .collect()
171	            .await;
172	        finalize(&session, &recorder).await;
173	
174	        // A genuine terminal event (RunCompleted/RunFailed) is the run's true
175	        // outcome; a cancel/timeout overrides ONLY when no terminal was observed
176	        // — i.e. it actually aborted the run in-flight. This closes the window
177	        // where a late cancel (e.g. during a suspending OnRunComplete hook) fires
178	        // after the terminal already went out. Cancellation is best-effort and
179	        // loses to a terminal that already occurred — see the Runner::run docs.
180	        // (SMA-421; deliberately revisits the SMA-321 precedence. The shared-core
181	        // hoist for durable runners is tracked as SMA-422.)
182	        let saw_terminal = collected
183	            .as_ref()
184	            .map(|r| r.events.iter().any(is_terminal))
185	            .unwrap_or(true); // Err(_) from collect() ⇔ a RunFailed was observed
186	
187	        match outcome.get() {
188	            Outcome::Cancelled if !saw_terminal => Err(RunError::Cancelled),
189	            Outcome::TimedOut if !saw_terminal => Err(RunError::Timeout),
190	            _ => collected,
191	        }
192	    }
193	
194	    async fn run_streamed(
195	        &self,
196	        agent: &(dyn Agent<Ctx> + '_),
197	        ctx: RunContext<Ctx>,
198	        input: AgentInput,
199	        config: RunConfig,
200	    ) -> Result<RunResultStreaming, RunError> {
201	        let timeout = config.timeout;
202	        let ctx = ctx.with_run_config(config);
203	        let cancel = ctx.cancel().clone();
204	        let session = ctx.session().clone();
205	        let failure = ctx.failure_handle();
206	
207	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
208	
209	        let stream = agent.run(ctx, merged).await?;
210	        let (controlled_stream, outcome) = controlled(stream, cancel, timeout);
211	        let rec_inspect = Arc::clone(&recorder);
212	        let mut recorded = controlled_stream
213	            .inspect(move |ev| {
214	                rec_inspect
215	                    .lock()
216	                    .expect("session recorder mutex poisoned")
217	                    .observe(ev)
218	            })
219	            .boxed();
220	
221	        let out = async_stream::stream! {
222	            let mut saw_terminal = false;
223	            let mut finalized = false;
224	            while let Some(ev) = recorded.next().await {
225	                // Finalize BEFORE exposing a terminal event: a consumer may stop
226	                // polling (and drop the stream) the moment it sees the terminal,
227	                // so anything after the `yield` could never run.
228	                if is_terminal(&ev) {
229	                    if !finalized {
230	                        finalize(&session, &recorder).await;
231	                        finalized = true;
232	                    }
233	                    saw_terminal = true;
234	                }
235	                yield ev;
236	            }
237	            // Synthesize a terminal ONLY when the run aborted in-flight (no real
238	            // terminal was ever yielded). Reaching here with `!saw_terminal` means
239	            // the loop never finalized, so finalize directly. A late cancel/timeout
240	            // that fired AFTER a real terminal — e.g. during a suspending
241	            // OnRunComplete hook — must NOT emit a second, synthetic terminal.
242	            // (SMA-421)
243	            if !saw_terminal {
244	                match outcome.get() {
245	                    Outcome::Cancelled => {
246	                        finalize(&session, &recorder).await;
247	                        yield AgentEvent::RunFailed { error: "run cancelled".to_owned() };
248	                    }
249	                    Outcome::TimedOut => {
250	                        finalize(&session, &recorder).await;
251	                        yield AgentEvent::RunFailed { error: "run timed out".to_owned() };
252	                    }
253	                    Outcome::Completed => {}
254	                }
255	            }
256	        };
257	        Ok(RunResultStreaming::with_failure(Box::pin(out), failure))
258	    }
259	}
