1	//! The client-side durable [`Runner`](paigasus_helikon_core::Runner)
2	//! implementation.
3	//!
4	//! [`TemporalRunner`](crate::runner::TemporalRunner) implements
5	//! [`paigasus_helikon_core::Runner`] by starting the durable agent-loop
6	//! workflow (the crate-internal `workflow` module) on a Temporal task queue,
7	//! awaiting its total [`crate::payloads::DurableRunOutcome`], and mapping that
8	//! onto the runner boundary via this crate's `error::outcome_to_run_result`.
9	//! The agent itself executes on the **worker**
10	//! ([`crate::worker::TemporalAgentWorker`]); this runner never runs the agent
11	//! locally — it only needs [`paigasus_helikon_core::Agent::name`] to address
12	//! the registered agent and to seed the session recorder.
13	//!
14	//! # Session semantics (mirrors `TokioRunner`)
15	//!
16	//! `run`/`run_streamed` load persisted history and seed the conversation as
17	//! `history ++ input.messages` (the session owns history, `input` is the new
18	//! turn), and finalize the run's events into the session on **every** exit
19	//! path — success, agent failure, cancellation, timeout, or infrastructure
20	//! error — matching `TokioRunner`'s finalize-on-every-exit guarantee. A
21	//! session read failure is a hard error (the run cannot faithfully resume from
22	//! an unreadable session); session writes are best-effort.
23	
24	use std::sync::{Arc, Mutex};
25	use std::time::Duration;
26	
27	use async_trait::async_trait;
28	use futures_util::stream::{self, StreamExt as _};
29	use paigasus_helikon_core::{
30	    Agent, AgentEvent, AgentInput, CancellationToken, FailureSlot, RunConfig, RunContext, RunError,
31	    RunResult, RunResultStreaming, Runner, Session, SessionRecorder,
32	};
33	use temporalio_client::{
34	    Client, WorkflowCancelOptions, WorkflowGetResultOptions, WorkflowStartOptions,
35	};
36	
37	use crate::error::outcome_to_run_result;
38	use crate::payloads::{DriverConfig, DurableRunOutcome, WorkflowInput};
39	
40	/// Configuration for a [`TemporalRunner`].
41	///
42	/// `#[non_exhaustive]`: construct via [`TemporalRunnerConfig::new`] and the
43	/// `with_*` builder methods, not a struct literal — this keeps adding a field
44	/// (e.g. the private `ctx_seed`) a non-breaking change.
45	#[derive(Debug, Clone)]
46	#[non_exhaustive]
47	pub struct TemporalRunnerConfig {
48	    /// Task queue the durable workflow (and its worker) are served on. Must
49	    /// match the task queue the [`crate::worker::TemporalAgentWorker`] polls.
50	    pub task_queue: String,
51	    /// Workflow id assigned per run.
52	    ///
53	    /// `None` (the default) mints a fresh `helikon-run-{uuid-v4}` per run,
54	    /// client-side. Set this only when the caller needs a deterministic
55	    /// workflow id (e.g. idempotent start / dedup); reusing the same id across
56	    /// concurrent runs is a Temporal id-reuse conflict.
57	    pub workflow_id: Option<String>,
58	    /// Backstop margin added to `RunConfig::timeout` when setting the hard
59	    /// Temporal **workflow-execution** timeout.
60	    ///
61	    /// The run deadline itself is a durable timer *inside* the workflow (so an
62	    /// expiry returns `TimedOut` with events-so-far); this execution timeout is
63	    /// only a safety backstop above it and would discard the outcome, so it is
64	    /// set generously above the durable timer. Default 60s.
65	    pub execution_timeout_margin: Duration,
66	    /// Optional request-scoped seed forwarded to the worker's seeded ctx
67	    /// factory. Private: set via [`Self::with_ctx_seed`]. Default `None`.
68	    ctx_seed: Option<serde_json::Value>,
69	}
70	
71	impl TemporalRunnerConfig {
72	    /// Construct a config for `task_queue` with the default workflow-id policy
73	    /// (`helikon-run-{uuid}`) and a 60s execution-timeout margin.
74	    pub fn new(task_queue: impl Into<String>) -> Self {
75	        Self {
76	            task_queue: task_queue.into(),
77	            workflow_id: None,
78	            execution_timeout_margin: Duration::from_secs(60),
79	            ctx_seed: None,
80	        }
81	    }
82	
83	    /// Attach a request-scoped seed forwarded (explicitly) to the worker's
84	    /// seeded ctx factory for every run this config drives. Recorded in
85	    /// Temporal history — keep it small and secret-free.
86	    pub fn with_ctx_seed(mut self, seed: serde_json::Value) -> Self {
87	        self.ctx_seed = Some(seed);
88	        self
89	    }
90	}
