92	/// A durable, Temporal-backed [`Runner`].
93	///
94	/// Holds a connected [`temporalio_client::Client`] and a
95	/// [`TemporalRunnerConfig`]; each `run` starts one durable workflow execution
96	/// on the configured task queue. Construct via [`TemporalRunner::new`].
97	pub struct TemporalRunner {
98	    client: Client,
99	    config: TemporalRunnerConfig,
100	}
101	
102	impl TemporalRunner {
103	    /// Build a runner from a connected client and its configuration.
104	    pub fn new(client: Client, config: TemporalRunnerConfig) -> Self {
105	        Self { client, config }
106	    }
107	
108	    /// Run the durable workflow to completion, racing the client's cancel
109	    /// token against the awaited result: a fired token requests cooperative
110	    /// workflow cancellation, after which the workflow still returns a total
111	    /// (`Cancelled`) outcome.
112	    async fn run_workflow(
113	        &self,
114	        input: WorkflowInput,
115	        timeout: Option<Duration>,
116	        cancel: CancellationToken,
117	    ) -> Result<DurableRunOutcome, RunError> {
118	        // Workflow id is minted client-side (never inside the workflow, which
119	        // must stay deterministic).
120	        let workflow_id = self
121	            .config
122	            .workflow_id
123	            .clone()
124	            .unwrap_or_else(|| format!("helikon-run-{}", uuid::Uuid::new_v4()));
125	
126	        let execution_timeout =
127	            timeout.map(|d| d.saturating_add(self.config.execution_timeout_margin));
128	        let start_opts = WorkflowStartOptions::new(self.config.task_queue.clone(), workflow_id)
129	            .maybe_execution_timeout(execution_timeout)
130	            .build();
131	
132	        let handle = self
133	            .client
134	            .start_workflow(
135	                crate::workflow::DurableAgentWorkflow::run,
136	                input,
137	                start_opts,
138	            )
139	            .await
140	            .map_err(|e| {
141	                RunError::Other(anyhow::anyhow!("failed to start temporal workflow: {e}"))
142	            })?;
143	
144	        let get_result = handle.get_result(WorkflowGetResultOptions::default());
145	        tokio::pin!(get_result);
146	        let mut requested_cancel = false;
147	        let outcome = loop {
148	            tokio::select! {
149	                result = &mut get_result => break result,
150	                // Once the run's cancel token fires, request cooperative
151	                // workflow cancellation once, then keep awaiting the (now
152	                // `Cancelled`) total outcome.
153	                () = cancel.cancelled(), if !requested_cancel => {
154	                    requested_cancel = true;
155	                    let _ = handle.cancel(WorkflowCancelOptions::default()).await;
156	                }
157	            }
158	        };
159	
160	        outcome.map_err(|e| RunError::Other(anyhow::anyhow!("temporal workflow failed: {e}")))
161	    }
162	
163	    /// Shared run path for both [`Runner::run`] and [`Runner::run_streamed`].
164	    ///
165	    /// Returns the run's events plus its mapped terminal result. The outer
166	    /// `Err` is reserved for a session **read** failure (load fails before the
167	    /// run starts); every other exit — including workflow start/await
168	    /// infrastructure failures — finalizes the session recorder and reports its
169	    /// outcome as the inner `Result`.
170	    async fn run_inner<Ctx>(
171	        &self,
172	        agent: &(dyn Agent<Ctx> + '_),
173	        ctx: RunContext<Ctx>,
174	        input: AgentInput,
175	        config: RunConfig,
176	    ) -> Result<(Vec<AgentEvent>, Result<RunResult, RunError>), RunError>
177	    where
178	        Ctx: Send + Sync + 'static,
179	    {
180	        let timeout = config.timeout;
181	        let max_turns = config.max_turns;
182	        let parallel_tool_call_limit = config.parallel_tool_call_limit;
183	
184	        let ctx = ctx.with_run_config(config);
185	        let cancel = ctx.cancel().clone();
186	        let session = ctx.session().clone();
187	
188	        // Session read failure is a hard error (mirrors `TokioRunner`).
189	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
190	
191	        let workflow_input = WorkflowInput {
192	            agent_name: agent.name().to_owned(),
193	            conversation: merged.messages,
194	            config: DriverConfig {
195	                max_turns,
196	                parallel_tool_call_limit: parallel_tool_call_limit.map(|n| n.get()),
197	            },
198	            timeout_ms: timeout.map(|d| d.as_millis() as u64),
199	            ctx_seed: self.config.ctx_seed.clone(),
200	        };
201	
202	        match self.run_workflow(workflow_input, timeout, cancel).await {
203	            Ok(outcome) => {
204	                {
205	                    let mut rec = recorder.lock().expect("session recorder mutex poisoned");
206	                    for event in &outcome.events {
207	                        rec.observe(event);
208	                    }
209	                }
210	                finalize(&session, &recorder).await;
211	                let events = outcome.events.clone();
212	                Ok((events, outcome_to_run_result(outcome)))
213	            }
214	            Err(infra) => {
215	                // Infra failure: still finalize (the recorder holds this turn's
216	                // new-turn input) before surfacing the error.
217	                finalize(&session, &recorder).await;
218	                Ok((Vec::new(), Err(infra)))
219	            }
220	        }
221	    }
222	}
