224	#[async_trait]
225	impl<Ctx> Runner<Ctx> for TemporalRunner
226	where
227	    Ctx: Send + Sync + 'static,
228	{
229	    async fn run(
230	        &self,
231	        agent: &(dyn Agent<Ctx> + '_),
232	        ctx: RunContext<Ctx>,
233	        input: AgentInput,
234	        config: RunConfig,
235	    ) -> Result<RunResult, RunError> {
236	        let (_events, result) = self.run_inner(agent, ctx, input, config).await?;
237	        result
238	    }
239	
240	    /// **Buffered, not live.** The durable workflow runs to completion first;
241	    /// the returned stream then replays the already-recorded
242	    /// [`AgentEvent`]s as an immediate, finite stream. Because persistence
243	    /// happened *before* the stream exists (a strictly stronger guarantee than
244	    /// the trait's warning), dropping the stream early loses nothing. Live
245	    /// token streaming across the workflow boundary is future work.
246	    ///
247	    /// On a failed run the terminal error is wired into the returned handle's
248	    /// [`FailureSlot`] and a terminal `RunFailed` event is guaranteed present,
249	    /// so [`RunResultStreaming::collect`] surfaces the typed
250	    /// [`RunError::Agent`] — matching `TokioRunner`.
251	    async fn run_streamed(
252	        &self,
253	        agent: &(dyn Agent<Ctx> + '_),
254	        ctx: RunContext<Ctx>,
255	        input: AgentInput,
256	        config: RunConfig,
257	    ) -> Result<RunResultStreaming, RunError> {
258	        let (mut events, result) = self.run_inner(agent, ctx, input, config).await?;
259	
260	        let failure = FailureSlot::new();
261	        let terminal_message = match result {
262	            Ok(_) => None,
263	            Err(RunError::Agent(err)) => {
264	                let message = err.to_string();
265	                failure.set(err);
266	                Some(message)
267	            }
268	            Err(other) => Some(other.to_string()),
269	        };
270	
271	        // `collect()` only reads the failure slot once it observes a terminal
272	        // `RunFailed` in the stream. The durable event log already carries one
273	        // for `AgentFailed` runs; synthesize one for the terminal states that
274	        // do not (cancellation/timeout/infra), so a failed run never collects
275	        // as `Ok`.
276	        if let Some(message) = terminal_message {
277	            if !matches!(events.last(), Some(AgentEvent::RunFailed { .. })) {
278	                events.push(AgentEvent::RunFailed { error: message });
279	            }
280	        }
281	
282	        Ok(RunResultStreaming::with_failure(
283	            stream::iter(events).boxed(),
284	            failure,
285	        ))
286	    }
287	}
