289	/// Snapshot the session into the merged input and seed a recorder with the
290	/// run's new-turn messages. A read failure is a hard error: the run cannot
291	/// faithfully resume from an unreadable session. (Mirrors
292	/// `TokioRunner::load_and_record`.)
293	async fn load_and_record(
294	    session: &Arc<dyn Session>,
295	    agent_name: &str,
296	    input: AgentInput,
297	) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
298	    let snapshot = session
299	        .snapshot()
300	        .await
301	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
302	    let mut recorder = SessionRecorder::new(agent_name);
303	    recorder.record_input(&input.messages);
304	
305	    let mut merged = AgentInput::new();
306	    merged.messages = snapshot.messages;
307	    merged.messages.extend(input.messages);
308	    Ok((merged, Arc::new(Mutex::new(recorder))))
309	}
310	
311	/// Post-run finalization: drain the recorder and append the run's events.
312	/// Persistence is best-effort — an append error is logged, never propagated.
313	/// (Mirrors `TokioRunner::finalize`.)
314	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
315	    let events = recorder
316	        .lock()
317	        .expect("session recorder mutex poisoned")
318	        .drain();
319	    if let Err(e) = session.append(&events).await {
320	        tracing::warn!(
321	            error = %e,
322	            "session persistence failed during finalize; run outcome unaffected"
323	        );
324	    }
325	}
