1	//! Error types for the Temporal-backed durable runtime.
2	
3	use serde::{Deserialize, Serialize};
4	
5	use crate::payloads::{DurableRunOutcome, RunStatusPayload};
6	
7	/// Map a total [`DurableRunOutcome`] onto the [`crate::error`]-external
8	/// [`paigasus_helikon_core::Runner`] boundary types.
9	///
10	/// This is the durable-runner mirror of `TokioRunner`'s terminal-outcome
11	/// handling: the workflow always returns a `DurableRunOutcome` (finalize on
12	/// every exit path), and this function projects its four terminal states onto
13	/// the runner's `Result<RunResult, RunError>`:
14	///
15	/// - [`RunStatusPayload::Completed`] → `Ok(RunResult)` whose `final_output` is
16	///   the concatenated [`paigasus_helikon_core::ContentPart::Text`] parts of the
17	///   final output (the `FinalOutput::as_text` convention), carrying the run's
18	///   events and cumulative usage.
19	/// - [`RunStatusPayload::AgentFailed`] → `Err(RunError::Agent(..))`, the typed
20	///   [`paigasus_helikon_core::AgentError`] reconstructed from the wire payload.
21	/// - [`RunStatusPayload::Cancelled`] → `Err(RunError::Cancelled)`.
22	/// - [`RunStatusPayload::TimedOut`] → `Err(RunError::Timeout)`.
23	pub(crate) fn outcome_to_run_result(
24	    outcome: DurableRunOutcome,
25	) -> Result<paigasus_helikon_core::RunResult, paigasus_helikon_core::RunError> {
26	    use paigasus_helikon_core::ContentPart;
27	
28	    let DurableRunOutcome {
29	        status,
30	        events,
31	        usage,
32	    } = outcome;
33	
34	    match status {
35	        RunStatusPayload::Completed(final_output) => {
36	            let final_text = final_output
37	                .content
38	                .iter()
39	                .filter_map(|part| match part {
40	                    ContentPart::Text { text } => Some(text.as_str()),
41	                    _ => None,
42	                })
43	                .collect::<Vec<_>>()
44	                .join("");
45	            // `RunResult` is `#[non_exhaustive]`, so it cannot be built with a
46	            // struct literal from outside `paigasus-helikon-core`; construct
47	            // via `Default` (which yields `RunResult<String>`) then assign.
48	            let mut result = paigasus_helikon_core::RunResult::default();
49	            result.final_output = final_text;
50	            result.events = events;
51	            result.usage = usage;
52	            Ok(result)
53	        }
54	        RunStatusPayload::AgentFailed(kind) => Err(paigasus_helikon_core::RunError::Agent(
55	            kind.into_agent_error(),
56	        )),
57	        RunStatusPayload::Cancelled => Err(paigasus_helikon_core::RunError::Cancelled),
58	        RunStatusPayload::TimedOut => Err(paigasus_helikon_core::RunError::Timeout),
59	    }
60	}
