236	/// Run the driver loop, racing it against the run-deadline timer and workflow
237	/// cancellation. Always returns a total outcome.
238	async fn drive(
239	    ctx: &WorkflowContext<DurableAgentWorkflow>,
240	    config: Arc<WorkflowActivityConfig>,
241	    input: WorkflowInput,
242	) -> DurableRunOutcome {
243	    let agent_name = input.agent_name.clone();
244	    let timeout_ms = input.timeout_ms;
245	    let parallel_limit = input.config.parallel_tool_call_limit;
246	    let ctx_seed = input.ctx_seed.clone();
247	
248	    // Single keyed lookup — deterministic, not a `HashMap` iteration.
249	    let plan = match config.plans.get(&agent_name) {
250	        Some(plan) => plan.clone(),
251	        None => return unknown_agent_outcome(&agent_name),
252	    };
253	
254	    let mut driver = DurableDriver::new(input, plan);
255	
256	    // Race the whole effect loop against (a) the durable run-deadline timer
257	    // and (b) cooperative cancellation. The `select!` block owns the borrow of
258	    // `driver` (via `effects`); it is released at the block's end, before
259	    // `driver.interrupt(..)` consumes the driver on an interruption. A natural
260	    // finish `return`s the outcome directly from inside the loop.
261	    let interrupt = {
262	        let effects = run_effects(
263	            ctx,
264	            &config,
265	            &agent_name,
266	            &ctx_seed,
267	            parallel_limit,
268	            &mut driver,
269	        )
270	        .fuse();
271	        let deadline = run_deadline(ctx, timeout_ms).fuse();
272	        let cancelled = ctx.cancelled();
273	        futures_util::pin_mut!(effects, deadline, cancelled);
274	
275	        temporalio_sdk::workflows::select! {
276	            outcome = effects => return outcome,
277	            _ = deadline => InterruptKind::TimedOut,
278	            _ = cancelled => InterruptKind::Cancelled,
279	        }
280	    };
281	
282	    driver.interrupt(interrupt)
283	}
